const upsertAssessment = `-- name: UpsertAssessment :one
INSERT INTO portfolio_assessments (portfolio_id, assessor_id, total_score, comment)
VALUES ($1, $2, $3, $4)
ON CONFLICT (portfolio_id) DO UPDATE SET assessor_id = EXCLUDED.assessor_id, total_score = EXCLUDED.total_score, comment = EXCLUDED.comment, updated_at = NOW()
RETURNING id
`

type UpsertAssessmentParams struct {
	PortfolioID pgtype.UUID    `json:"portfolio_id"`
	AssessorID  pgtype.UUID    `json:"assessor_id"`
	TotalScore  pgtype.Numeric `json:"total_score"`
	Comment     string         `json:"comment"`
}

func (q *Queries) UpsertAssessment(ctx context.Context, arg UpsertAssessmentParams) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, upsertAssessment,
		arg.PortfolioID,
		arg.AssessorID,
		arg.TotalScore,
		arg.Comment,
	)
	var id pgtype.UUID
	err := row.Scan(&id)
	return id, err
}

